<?php require "../config.php";require_role("admin");if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO programs(name,faculty,level,duration,description) VALUES(?,?,?,?,?)");$s->bind_param("sssis",$_POST["name"],$_POST["faculty"],$_POST["level"],$_POST["duration"],$_POST["description"]);$s->execute();header("Location: programs.php");exit;}if(isset($_GET["delete"])){$s=$conn->prepare("DELETE FROM programs WHERE id=?");$s->bind_param("i",$_GET["delete"]);$s->execute();header("Location: programs.php");exit;}$rows=$conn->query("SELECT * FROM programs ORDER BY id DESC");$page_title="Programs";require "../includes/header.php";?><section class="portal-shell pb-5"><div class="container"><h1 class="section-title">Programs</h1><div class="row g-4 mt-2"><div class="col-lg-4"><form method="post" class="dashboard-card"><input class="form-control my-2" name="name" placeholder="Program name" required><input class="form-control my-2" name="faculty" placeholder="Faculty" required><input class="form-control my-2" name="level" placeholder="Undergraduate" required><input class="form-control my-2" name="duration" type="number" placeholder="4" required><textarea class="form-control my-2" name="description" placeholder="Description"></textarea><button class="btn btn-adventure rounded-pill">Add Program</button></form></div><div class="col-lg-8"><div class="table-wrap"><table class="table"><tr><th>Program</th><th>Faculty</th><th></th></tr><?php while($p=$rows->fetch_assoc()):?><tr><td><?=e($p["name"])?></td><td><?=e($p["faculty"])?></td><td><a class="text-danger" href="?delete=<?=$p["id"]?>" onclick="return confirm('Delete?')">Delete</a></td></tr><?php endwhile;?></table></div></div></div></div></section><?php require "../includes/footer.php";?>